}

public class Icon : Control
{
    public static readonly StyledProperty<IconName> KindProperty =
        AvaloniaProperty.Register<Icon, IconName>(nameof(Kind));

    public static readonly StyledProperty<double> SizeProperty =
        AvaloniaProperty.Register<Icon, double>(nameof(Size), 16.0);

    public static readonly StyledProperty<double> StrokeWidthProperty =
        AvaloniaProperty.Register<Icon, double>(nameof(StrokeWidth), 2.0);

    public static readonly StyledProperty<ShellToken> TokenProperty =
        AvaloniaProperty.Register<Icon, ShellToken>(nameof(Token), ShellToken.Foreground);

    // Explicit color; overrides Token when set.
    public static readonly StyledProperty<Color?> ColorProperty =
        AvaloniaProperty.Register<Icon, Color?>(nameof(Color));

    // The token's brush, kept in sync with the theme by a resource binding.
    private static readonly StyledProperty<IBrush?> TintProperty =
        AvaloniaProperty.Register<Icon, IBrush?>("Tint");

    private static readonly Dictionary<IconName, Geometry?> Geometries = new();

    static Icon()
    {
        AffectsMeasure<Icon>(SizeProperty);
        AffectsRender<Icon>(KindProperty, SizeProperty, StrokeWidthProperty, ColorProperty, TintProperty);
        TokenProperty.Changed.AddClassHandler<Icon>((icon, _) => icon.Token(TintProperty, icon.Token));
        IsHitTestVisibleProperty.OverrideDefaultValue<Icon>(false);
        HorizontalAlignmentProperty.OverrideDefaultValue<Icon>(HorizontalAlignment.Center);
        VerticalAlignmentProperty.OverrideDefaultValue<Icon>(VerticalAlignment.Center);
    }

    public Icon() => this.Token(TintProperty, Token);

    public IconName Kind
    {
        get => GetValue(KindProperty);
        set => SetValue(KindProperty, value);
    }

    public double Size
    {
        get => GetValue(SizeProperty);
        set => SetValue(SizeProperty, value);
    }

    public double StrokeWidth
    {
        get => GetValue(StrokeWidthProperty);
        set => SetValue(StrokeWidthProperty, value);
    }

    public ShellToken Token
    {
        get => GetValue(TokenProperty);
        set => SetValue(TokenProperty, value);
    }

    public Color? Color
    {
        get => GetValue(ColorProperty);
        set => SetValue(ColorProperty, value);
    }

    protected override Size MeasureOverride(Size availableSize) => new(Size, Size);

    public override void Render(DrawingContext context)
    {
        var brush = Color is { } color ? new SolidColorBrush(color) : GetValue(TintProperty);
        if (GetGeometry(Kind) is not { } geometry || brush is null) return;
        // Scale the 24x24 grid to Size; the stroke scales with it so icons keep Lucide's weight.
        var scale = Size / 24.0;
        using (context.PushTransform(Matrix.CreateScale(scale, scale)))
            context.DrawGeometry(null, new Pen(brush, StrokeWidth, lineCap: PenLineCap.Round, lineJoin: PenLineJoin.Round), geometry);
    }

    private static Geometry? GetGeometry(IconName kind)
    {
        if (!Geometries.TryGetValue(kind, out var geometry))
        {
            var data = IconPaths.Get(kind);
            geometry = string.IsNullOrEmpty(data) ? null : Geometry.Parse(data);
            Geometries[kind] = geometry;
        }
        return geometry;
    }
}
